function productDefaults(){defaults({packing:[{id:'water',name:'水和随身用品',done:false},{id:'weather',name:'核对天气与开放信息',done:false}],editPlan:''})}
function productRender(){const e=state.plans.find(x=>x.id===p.editPlan);put(`<div class="grid"><div>${box('建立自己的旅行方案',`<form id="trip-plan" class="stack">${field('方案名称','name','text',e?.name||'','required maxlength="60"')}<div class="fields">${select('主题','tag',['自然','文化','玩乐'],e?.tag)}${field('预计全家总费用 / 元','cost','number',e?.cost||100,'required min="0" max="100000"')}</div>${field('依次经过的地点（用 → 分隔）','route','text',e?.route.join(' → ')||'','required maxlength="200"')}<button class="primary">${e?'保存方案修改':'添加候选方案'}</button></form>${state.plans.map(x=>`<div class="item"><span>${esc(x.name)}</span><div class="row"><button data-edit="${x.id}" class="small">修改</button><button data-remove="${x.id}" class="small">移除</button></div></div>`).join('')}`)}${box('家庭偏好覆盖',`<p>${state.preferences.length} 位成员参与，${new Set(state.preferences.map(x=>x.preference)).size} 种偏好。</p>${ranked().map(x=>`<p>${esc(x.name)}：照顾 ${x.votes} / ${state.preferences.length} 位成员偏好 · ${x.fit?'预算内':'超预算'}</p>`).join('')}${note('每人当前一项偏好、等权匹配；排序可解释，最终仍由全家协商。')}`)}</div><div>${box('出门前的准备清单',rows(p.packing,x=>`<label class="checkline item"><input data-pack="${x.id}" type="checkbox" ${x.done?'checked':''}>${esc(x.name)}</label>`)+`<form id="pack" class="stack">${field('新增准备事项','name','text','','required maxlength="60"')}<button>添加事项</button></form>`)}${box('导出路线与预算',btn('导出候选方案 CSV','trip-csv',''))}</div></div>`);form('trip-plan',v=>{const route=v.route.split(/[→>]/).map(x=>x.trim()).filter(Boolean);if(route.length<2)return toast('至少写两个地点，用 → 分隔');const plan={...v,cost:+v.cost,route};if(e)Object.assign(e,plan);else state.plans.push({...plan,id:uid()});p.editPlan='';commit()});deleteButtons('edit',id=>{p.editPlan=id;commit()});deleteButtons('remove',id=>{state.plans=state.plans.filter(x=>x.id!==id);if(state.selected===id)state.selected=null;p.editPlan='';commit()});$$('[data-pack]').forEach(x=>x.onchange=()=>{p.packing.find(y=>y.id===x.dataset.pack).done=x.checked;commit()});form('pack',v=>{p.packing.push({...v,id:uid(),done:false});commit()});on('trip-csv',()=>exportCSV('旅行方案.csv',['名称','主题','预计费用','路线'],state.plans.map(x=>[x.name,x.tag,x.cost,x.route.join(' → ')])))}
